import { useEffect, useState } from 'react';
import { PinInterface } from '~/entities/pin/ui/pin-interface';
import { PinInteractionMode } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';

type InputPinNumberProps = {
  isShow?: boolean;
  handleCompleteInput?: (isSuccess: boolean) => void;
};

export const InputPinNumberPage = (props: InputPinNumberProps) => {
  const [isOpenBottomSheet, setIsOpenBottomSheet] = useState(true);
  const handleCloseBottomSheet = () => {
    setIsOpenBottomSheet(false);
  };

  useEffect(() => {
    if (props.isShow) {
      setIsOpenBottomSheet(true);
    }
  }, [props]);
  return (
    <BottomSheet afterLeave={() => null} open={isOpenBottomSheet} onClose={handleCloseBottomSheet}>
      <PinInterface
        type={PinInteractionMode.인증}
        title={i18n.t('pin:titleInputPin')}
        message={i18n.t('pin:messageInputPin')}
        step={1}
        prevPin={''}
        pin={''}
        isError={false}
        handleCompleteInput={() => {
          props.handleCompleteInput?.(true);
          setIsOpenBottomSheet(false);
        }}
      />
    </BottomSheet>
  );
};
